    n = length(array)

    // Outer loop: iterate through each pass
    for (i = 0; i < n; i += 1):
        swapped = False  // Flag to track if any swaps occur in this pass

        // Inner loop: compare adjacent elements
        for (j = 0; j < n - i - 1; j += 1):
            @mark<j, outline, yellow> if (array[j] > array[j + 1]):
                @mark<j, highlight, green> swap(array[j], array[j + 1])
                swapped = True  // A swap occurred, so set flag
            end if
        end for

        // If no swaps occurred, the array is sorted
        if (swapped == False):
            break
        end if
    end for

    return array
end fun

