fun Max_Subarray_Sum(@init<table> nums):
    // Initialize variables to track maximum sum and current sum
    @mark<maxSoFar, outline, yellow> maxSoFar = nums[0]
    @mark<maxEndingHere, outline, yellow> maxEndingHere = nums[0]

    // Iterate through the rest of the array starting from index 1
    for (i = 1, i < length(nums), i += 1):
        // Either extend the existing subarray or start a new one
        @mark<i, outline, yellow> if (maxEndingHere < 0):
            @mark<i, text, fg> maxEndingHere = nums[i]
        else:
            @mark<i, text, fg> maxEndingHere += nums[i]
        end if

        // Update global maximum if current ending sum is greater
        @mark<i, highlight, green> if (maxEndingHere > maxSoFar):
            @mark<i, text, fg> maxSoFar = maxEndingHere
        end if
    end for

    @log<"Maximum subarray sum: "> return maxSoFar
end fun

