fun Rotate_Left(@init<table> array, k):
    n = length(array)

    // Handle cases where k is larger than array size
    k = k % n

    // No rotation needed
    if (k == 0):
        @log<"No rotation needed"> return array
    end if

    // Step 1: Reverse entire array
    @mark<n, highlight, green> Reverse(array, 0, n - 1)

    // Step 2: Reverse first k elements
    @mark<k, highlight, green> Reverse(array, 0, k - 1)

    // Step 3: Reverse remaining n-k elements
    @mark<n-k, highlight, green> Reverse(array, k, n - 1)

    return array
end fun

